actions.script:
query = q || ''
total = 0
totalRelation = 'eq'
results = []
facetCounts = {}
capabilities = ec.search.isAvailable() ? ec.search.capabilities() : []
if (!ec.search.isAvailable()) { ec.message.addError('Search is not configured'); return }

// the organization fields of each document type; a type that is not here has no organization scope
const orgFields = {MantleParty: ['ownerPartyId'], MantleProduct: ['ownerPartyId'], MantleFacility: ['ownerPartyId'],
    MantleAsset: ['ownerPartyId'], MantleOrder: ['parts.vendorPartyId', 'parts.customerPartyId'],
    MantleInvoice: ['fromPartyId', 'toPartyId'], MantleShipment: ['fromPartyId', 'toPartyId'],
    MantleCommunicationEvent: [], MantleWikiPage: null}

// the user's organization limit, as the find filters have it
if (ec.user.context.filterOrgIds === undefined) ec.service.sync().name('mantle.party.PartyServices.setup#UserOrganizationInfo').call()
const findFilters = ec.artifactExecution.getFindFiltersForUser('mantle.party.Party')
const filterSetId = findFilters ? findFilters[0].entityFilterSetId : null
let orgIds = null
if (filterSetId === 'MANTLE_USER_ORG') orgIds = (ec.user.context.filterOrgIds || []).slice()
else if (filterSetId === 'MANTLE_ACTIVE_ORG' && ec.user.context.activeOrgId) orgIds = [ec.user.context.activeOrgId]

// the document types the user may see: view authz on the primary entity, and an organization scope under a limit
const requested = entityType ? String(entityType).split(',').map((type) => type.trim()).filter((type) => type) : null
const documents = {}
for (const documentId of ec.search.documentTypes({indexName: indexName})) {
    if (requested && !requested.includes(documentId)) continue
    const document = ec.entity.find('moqui.entity.document.DataDocument').condition('dataDocumentId', documentId)
            .useCache(true).one()
    if (document == null || !ec.artifactExecution.isPermitted(document.primaryEntityName, 'AT_ENTITY', 'view')) continue
    const fields = Object.prototype.hasOwnProperty.call(orgFields, documentId) ? orgFields[documentId] : []
    if (orgIds != null && fields != null && fields.length === 0) continue
    documents[documentId] = {name: document.documentName, primaryEntityName: document.primaryEntityName,
            orgFields: fields, roles: {}, links: []}
}
const types = Object.keys(documents)
if (types.length === 0) return

// display roles and links of each type
for (const type of types) {
    for (const field of ec.entity.find('moqui.entity.document.DataDocumentField').condition('dataDocumentId', type)
            .useCache(true).list()) {
        if (!field.searchRole) continue
        const path = String(field.fieldPath)
        documents[type].roles[field.searchRole] = field.fieldNameAlias || path.substring(path.lastIndexOf(':') + 1)
    }
    documents[type].links = Array.from(ec.entity.find('moqui.entity.document.DataDocumentLink').condition('dataDocumentId', type)
            .condition('linkSet', linkSet).orderBy('linkSeqId').useCache(true).list())
}

// the trusted filter: per type, the type and its organization limit
const typeClauses = types.map((type) => {
    const all = [{field: {name: '_document', op: 'eq', value: type}}]
    const fields = documents[type].orgFields
    if (orgIds != null && fields != null) {
        const values = type === 'MantleParty' ? orgIds.concat(['_NA_']) : orgIds
        all.push({bool: {any: fields.map((name) => ({field: {name: name, op: 'in', values: values}}))}})
    }
    return {bool: {all: all}}
})
const filterClauses = [{bool: {any: typeClauses}}]
// the caller's field filters narrow too; they do not score
for (const [name, value] of Object.entries(filters || {})) {
    if (value == null || value === '') continue
    filterClauses.push(Array.isArray(value) ? {field: {name: name, op: 'in', values: value}} : {field: {name: name, op: 'eq', value: value}})
}
const filter = {bool: {all: filterClauses}}

// the query by mode
const needs = (capability, what) => {
    if (capabilities.includes(capability)) return true
    ec.message.addError(`${what} is not available: the search backend does not have the ${capability} capability`)
    return false
}
let lexicalQuery = query.trim() ? ec.search.parseQuery(elasticQueryAutoWildcard(query, false)) : 'match_all'
const request = {documentType: types, filter: filter, offset: offset, limit: limit}
if (near && near.terms) {
    if (!needs('proximity', 'A near search')) return
    lexicalQuery = {near: {terms: Array.isArray(near.terms) ? near.terms.join(' ') : String(near.terms), distance: near.distance || 0}}
}
if (mode === 'autocomplete') {
    if (!needs('autocomplete', 'Autocomplete')) return
    request.query = query.trim() ? {suggest: {text: query}} : 'match_all'
} else if (mode === 'semantic' || mode === 'hybrid') {
    if (!needs(mode, `A ${mode} search`)) return
    request.query = lexicalQuery
    request.retrieval = mode
    request.text = query
} else {
    request.query = lexicalQuery
}
const highlightFields = new Set()
for (const type of types) for (const role of ['title', 'subtitle', 'code']) {
    if (documents[type].roles[role]) highlightFields.add(documents[type].roles[role])
}
if (highlight) request.highlight = Array.from(highlightFields)

const page = ec.search.search(request)
total = page.total
totalRelation = page.totalRelation || 'eq'

for (const hit of page.hits) {
    const document = documents[hit.documentId]
    const body = hit.body || {}
    // the entity database decides: a record now gone or outside the user's filters is not returned
    const keys = ec.entity.makeValue(document.primaryEntityName).getPrimaryKeys()
    const keyNames = Object.keys(keys)
    const key = {}
    const idParts = String(hit.id).split('::')
    keyNames.forEach((name, index) => { key[name] = body[name] != null ? body[name] : idParts[index] })
    if (ec.entity.find(document.primaryEntityName).condition(key).one() == null) continue

    const role = (name) => document.roles[name] ? body[document.roles[name]] : null
    const highlights = hit.highlights || {}
    const fragments = Object.values(highlights).flat()
    const link = document.links.find((candidate) => !candidate.linkCondition || ec.resource.condition(candidate.linkCondition, '', body))
    const roleFields = new Set(Object.values(document.roles))
    const attributes = {}
    for (const [name, value] of Object.entries(body)) {
        if (value == null || typeof value === 'object' || roleFields.has(name) || keyNames.includes(name)) continue
        attributes[name] = value
    }
    results.push({entityType: hit.documentId, entityTypeName: document.name, key: key, id: hit.id,
        title: role('title') || hit.id, subtitle: role('subtitle'), code: role('code'), category: role('category'),
        snippet: fragments.length ? fragments[0] : null, highlights: highlights, score: hit.score,
        url: link ? ec.resource.expand(link.linkUrl, '', body) : null, linkLabel: link ? link.label : null,
        attributes: attributes})
}

// facets over the whole authorized match, not the page
const facetList = facets ?? []
if (facetList.length) {
    const facetFilter = {bool: {all: [request.query === 'match_all' || request.query == null ? 'match_all' : lexicalQuery, filter]}}
    if (facetList.includes('entityType')) {
        const counts = ec.search.aggregate({documentType: types, filter: facetFilter, aggs: {types: {terms: {field: '_document', size: types.length}}}})
        facetCounts.entityType = counts.types.buckets.map((bucket) =>
                ({value: bucket.key, label: documents[bucket.key] ? documents[bucket.key].name : bucket.key, count: bucket.doc_count}))
    }
    const categoryField = types.length === 1 ? documents[types[0]].roles.category : null
    if (facetList.includes('category') && categoryField) {
        const counts = ec.search.aggregate({documentType: types[0], filter: facetFilter, aggs: {categories: {terms: {field: categoryField, size: 50}}}})
        facetCounts.category = counts.categories.buckets.map((bucket) => ({value: bucket.key, label: bucket.key, count: bucket.doc_count}))
    }
}
